237	func (store *UniversalRedis2Store) removeOrphanedDirectoryListMember(ctx context.Context, dirListKey string, path util.FullPath, fileName string) {
238		if err := store.Client.ZRem(ctx, dirListKey, fileName).Err(); err != nil {
239			return
240		}
241	
242		// InsertEntry writes the value before adding the member, so a value present
243		// again here may belong to an insert that found the member still in place
244		// and whose ZAddNX was therefore a no-op.
245		exists, err := store.Client.Exists(ctx, store.getKey(string(path))).Result()
246		if err == nil && exists == 0 {
247			return
248		}
249	
250		store.Client.ZAddNX(ctx, dirListKey, redis.Z{Score: 0, Member: fileName})
251	}
